"""Checks for the Wormholes part 4 mockup (python3 -I test_rt.py wh_part4_mockup.html shots/). A fresh page per group, 1440 and 390 px."""
import os, sys
from playwright.sync_api import sync_playwright
PAGE = 'file://' + os.path.abspath(sys.argv[1]); SHOTS = sys.argv[2]; os.makedirs(SHOTS, exist_ok=True)
fails, n = [], 0
def ok(c, what):
    global n; n += 1
    if not c: fails.append(what); print('FAIL', what)
JITA, RENS, TAMA, CJ, AMARR = 30000142, 30002510, 30002813, 30000772, 30002187
def page(p, w, h):
    b = p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg = b.new_page(viewport={'width': w, 'height': h}, has_touch=w < 600, is_mobile=w < 600); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(PAGE); pg.wait_for_function('window.__MKREADY || window.__MKERR', timeout=60000)
    ok(not pg.evaluate('window.__MKERR'), f'{w}: boot ' + str(pg.evaluate('window.__MKERR')))
    pg.wait_for_timeout(400)
    return b, pg, errs
def scene(pg, s): pg.evaluate(f"RTscene('{s}')"); pg.wait_for_timeout(700)
def txt(pg, sel): return pg.evaluate(f"(document.querySelector({sel!r}) || {{}}).innerText || ''")
with sync_playwright() as p:
    for w, h in [(1440, 900), (390, 844)]:
        # 1. Routes: one row per pin plus the quick rows, each with its strip; worked out from where you are
        b, pg, errs = page(p, w, h)
        rows = pg.evaluate("[...document.querySelectorAll('#whPnRt .rt-row')].map(r => [r.querySelector('.rt-l1').innerText.replace(/\\s+/g, ' '), r.querySelectorAll('.rt-q').length])")
        names = ' | '.join(r[0] for r in rows)
        ok(len(rows) == 7 and 'Home' in names and 'nearest highsec' in names and 'nearest lowsec' in names, f'{w}: quick rows and 4 pins {rows}')
        dq = next(r for r in rows if '1DQ1-A' in r[0])
        lines = pg.evaluate("(() => { const r = [...document.querySelectorAll('#whPnRt .rt-row')].find(r => /1DQ1-A/.test(r.textContent)); return new Set([...r.querySelectorAll('.rt-q')].map(q => Math.round(q.getBoundingClientRect().top))).size; })()")
        ok(dq[1] == 40 and lines >= 2, f'{w}: a 40-jump route wraps its strip onto {lines} lines {dq[0]}')
        tip = (lambda: (pg.evaluate("(() => { const r = [...document.querySelectorAll('#whPnRt .rt-row')].find(r => /1DQ1-A/.test(r.textContent)); const q = r.querySelectorAll('.rt-q'); q[q.length - 1].dispatchEvent(new PointerEvent('pointerover', {bubbles: true, pointerType: 'mouse'})); })()"), pg.wait_for_timeout(250), txt(pg, '#whPnRt [data-rt-tip]'))[2])()
        ok('1DQ1-A' in tip and 'Delve' in tip, f'{w}: hovering the last square on the second line {tip!r}')
        jita = next(r for r in rows if 'Jita' in r[0] and 'nearest' not in r[0])
        ok(jita[1] == 5 and ' 5' in jita[0], f'{w}: Jita row: 5 jumps, 5 squares {jita}')
        ok(pg.evaluate("(() => { const r = [...document.querySelectorAll('#whPnRt .rt-row')].find(r => /Jita/.test(r.textContent) && !/nearest/.test(r.textContent)); const q = [...r.querySelectorAll('.rt-q')]; return q[0].classList.contains('hole') && !q[0].classList.contains('j') && q.slice(1).every(x => !x.classList.contains('hole')); })()"), f'{w}: the hole into Tama is round, the gates square')
        ok(pg.evaluate("[...document.querySelectorAll('#whPnRt .rt-q.j')].every(q => getComputedStyle(q).backgroundColor === 'rgb(169, 139, 216)')"), f'{w}: J-space squares in the wormhole colour')
        def hover(rowpat, k):
            pg.evaluate(f"(() => {{ const r = [...document.querySelectorAll('#whPnRt .rt-row')].find(r => /{rowpat}/.test(r.querySelector('.rt-l1').textContent)); const q = r.querySelectorAll('.rt-q')[{k}]; q.dispatchEvent(new PointerEvent('pointerover', {{bubbles: true, pointerType: 'mouse'}})); }})()"); pg.wait_for_timeout(250)
            return txt(pg, '#whPnRt [data-rt-tip]')
        tip = hover('Jita', 0)
        ok('J122515 → Tama · TUV-907 (K162) · end of life' in tip and 'The Citadel' in tip, f'{w}: hovering the hole: the step, its ID and warning {tip!r}')
        ok(pg.evaluate("!!RT.hov && [...document.querySelectorAll('#whPnRt .rt-row')].find(r => /Jita/.test(r.textContent) && !/nearest/.test(r.textContent)).querySelectorAll('.rt-strip.hov .rt-q:not(.on)').length === 4"), f'{w}: the other squares dim; the map shows that row')
        tip = hover('Jita', 4)
        ok('Jita' in tip and 'The Forge' in tip and '→' not in tip, f'{w}: hovering a gate: system, security, region {tip!r}')
        tip = hover('J144153', 1)
        ok('J102057 → J144153' in tip and 'not known' not in tip, f'{w}: a hole with no recorded ID: system to system, no "ID not known" {tip!r}')
        ok(pg.evaluate("document.querySelectorAll('#whPnRt [data-rt-go], #whPnRt .rt-go').length") == 0, f'{w}: no Set destination button (the owner: show the route as the panel draws it)')
        ok(pg.evaluate("document.querySelectorAll('.wh-rail button').length") == 2 and pg.evaluate("document.querySelector('[data-wh-rp=rt]').getAttribute('aria-pressed')") == 'true', f'{w}: two rail buttons, Routes pressed')
        # pin and unpin; kept in this browser
        pg.fill('[data-rt-typed]', 'Rens'); pg.click('[data-rt-form] button[type=submit]'); pg.wait_for_timeout(300)
        ok(30002510 in pg.evaluate("JSON.parse(localStorage.getItem('tvWhRoutes')).pins"), f'{w}: a typed system pinned and kept')
        pg.evaluate("document.querySelector('#whPnRt [data-rt-rm=\"30002510\"]').click()"); pg.wait_for_timeout(300)
        ok(30002510 not in pg.evaluate("JSON.parse(localStorage.getItem('tvWhRoutes')).pins"), f'{w}: × unpins')
        pg.fill('[data-rt-typed]', 'Nowhere'); pg.click('[data-rt-form] button[type=submit]'); pg.wait_for_timeout(300)
        ok('isn’t a system the page knows' in txt(pg, '#whPnRt'), f'{w}: unknown name said')
        ok('Pin route' in pg.evaluate("whMenuHtml(30002510)") and 'Routes from here' in pg.evaluate("whMenuHtml(30002510)"), f'{w}: the map menu pins (the owner: right-click a system)')
        pg.evaluate("whS.menu = 30002510; whMenuAct('pin')"); pg.wait_for_timeout(300)
        ok(30002510 in pg.evaluate("RT.pins") and 'Unpin route' in pg.evaluate("whMenuHtml(30002510)"), f'{w}: pinned from the menu')
        # statuses don't change a route (Q2); shortest
        before = pg.evaluate("JSON.stringify(RTroute().out.map(r => r.hops && r.hops.map(h => h.b)))")
        pg.evaluate(f"whS.mk[{TAMA}] = {{st: 'danger'}}; whMkSave()")
        ok(pg.evaluate("JSON.stringify(RTroute().out.map(r => r.hops && r.hops.map(h => h.b)))") == before, f'{w}: a Dangerous status leaves the routes as they were')
        pg.click('[data-rt-short]'); pg.wait_for_timeout(300)
        ok(pg.evaluate("RT.short && JSON.parse(localStorage.getItem('tvWhRoutes')).short") and 'Shortest' in txt(pg, '[data-rt-set]'), f'{w}: Shortest switch kept')
        pg.click('[data-rt-short]'); pg.wait_for_timeout(200)
        if w < 600:
            hs = pg.evaluate("[...document.querySelectorAll('#whPnRt .rt-rm, #whPnRt .rt-strip, .wh-rail button')].map(e => Math.round(e.getBoundingClientRect().height))")
            ok(min(hs) >= 44, f'{w}: 44 px targets on a phone (the strip is one target, scrubbed by a finger) {sorted(set(hs))}')
            ok(pg.evaluate("(() => { const p = document.querySelector('#whPnRt'); return p.scrollWidth <= p.clientWidth; })()"), f'{w}: no sideways scroll in the panel')
        # 2. recomputed when you move: out in k-space at Tama
        scene(pg, 'out')
        r2 = pg.evaluate("RTroute().out.map(r => [r.kind, r.id, r.hops ? r.hops.length : -1])")
        ok(any(k == 'pin' and i == JITA and n == 4 for k, i, n in r2) and any(k == 'home' and n == 2 for k, i, n in r2), f'{w}: after the jump out: Jita 4, Home 2 {r2}')
        ok(not any(k == 'ls' for k, i, n in r2), f'{w}: no "nearest lowsec" row while you are in lowsec')
        pg.screenshot(path=f'{SHOTS}/out_{w}.png')
        # 3. Routes from here
        scene(pg, 'here')
        ok(pg.evaluate("RT.from === RTJ.C") and 'From where you are' in txt(pg, '#whPnRt'), f'{w}: start set by the menu')
        pg.click('[data-rt-me]'); pg.wait_for_timeout(300)
        ok(pg.evaluate("RT.from === null"), f'{w}: back to from where you are')
        # 4. Signatures by type
        scene(pg, 'sigs')
        ids = pg.evaluate("[...document.querySelectorAll('.wh-lt.sg [data-wh-lr]')].map(e => e.dataset.whLr)")
        ok(ids == ['KLM-552', 'DEF-404', 'TUV-907', 'ABC-123', 'XYZ-789', 'QRS-210', 'RST-777', 'GHI-611', 'NOP-318'], f'{w}: unscanned first, then the game\'s group order (Q5), then paste order {ids}')
        ok(pg.evaluate("[{id: 'a', grp: 'Combat Site'}, {id: 'b', grp: 'Ore Site'}, {id: 'c', grp: 'Relic Site'}, {id: 'd', grp: 'Mystery Site'}, {id: 'e', grp: ''}].sort(WH_SG_SORT.ty).map(x => x.id).join('')") == 'ecbad', f'{w}: ore after relic, combat after ore, a group the page doesn\'t list last')
        ok(pg.evaluate("(document.querySelector('.wh-lt.sg [data-wh-ls=ty]') || {}).textContent || ''").startswith('Type'), f'{w}: a Type heading')
        ok(pg.evaluate("document.querySelector('.wh-lt.sg [data-wh-ls=ty]').closest('[role=columnheader]').getAttribute('aria-sort')") == 'ascending', f'{w}: Type is the sort (Q6)')
        pg.evaluate("whScanApply(RTJ.B, ['ABC-123\\tCosmic Signature\\tWormhole\\tUnstable Wormhole\\t100.0%\\t1 AU', 'RST-777\\tCosmic Signature\\tData Site\\tUnsecured Perimeter Comms Relay\\t100.0%\\t1 AU', 'TUV-907\\tCosmic Signature\\tWormhole\\tUnstable Wormhole\\t100.0%\\t1 AU'].join('\\n')); whS.pn = {}; whPaint(true)")
        pg.wait_for_timeout(300)
        ids = pg.evaluate("[...document.querySelectorAll('.wh-lt.sg [data-wh-lr]')].map(e => e.dataset.whLr)")
        ok(ids.index('ABC-123') < ids.index('TUV-907') and ids.index('RST-777') < ids.index('QRS-210'), f'{w}: the latest paste\'s order wins, the rest after (Q7) {ids}')
        if w < 600: ok(pg.evaluate("document.querySelector('.wh-lt.sg [data-wh-ls=ty]').getBoundingClientRect().height") >= 30, f'{w}: Type heading pressable')
        # 5. effects
        scene(pg, 'eff')
        eff = pg.evaluate("[...document.querySelectorAll('[data-rt-eff] li')].map(e => e.innerText)")
        ok(len(eff) == 5 and 'Shield HP +58%' in eff and any('resists worse' in x for x in eff), f'{w}: a C3 Pulsar\'s numbers {eff}')
        pg.evaluate("whSelect(RTJ.C)"); pg.wait_for_timeout(300)
        ok(pg.evaluate("document.querySelectorAll('[data-rt-eff]').length") == 0, f'{w}: no effect, no list')
        # 6. Intel: the auto-added holes, the setting, the ring
        st = pg.evaluate(f"(() => {{ const r = itWhStore().rep; return [{CJ}, {TAMA}, {RENS}].map(k => r[k] ? [r[k].src, !!r[k].jw, (r[k].info || {{}}).cls || ''] : null); }})()")
        ok(all(x and x[0] == 'you' and x[1] for x in st), f'{w}: C-J6MT, Tama and Rens added by your jumps {st}')
        scene(pg, 'intel')
        rows = txt(pg, '.it-whp-rows')
        ok('you jumped into' in rows and 'Wolf-Rayet' in rows, f'{w}: rows say where you jumped')
        ok(pg.evaluate(f"!!itm.wh.mark.get(itGraphGet().at.get({CJ}))"), f'{w}: C-J6MT ringed on the map (every filter)')
        ok('Wolf-Rayet: ' in pg.evaluate("[...document.querySelectorAll('.it-whp-by[title]')].map(e => e.title).join('|')"), f'{w}: the effect\'s numbers in the row\'s hover')
        pg.screenshot(path=f'{SHOTS}/intel_{w}.png')
        pg.evaluate(f"(() => {{ for(const l of whS.st.links) if(l.a === {CJ} || l.b === {CJ}) l.seen = Date.now() - 30 * 3600e3; delete itWhStore().rep[{CJ}]; }})()")
        ok(not pg.evaluate(f"!!itMapWh().mark.get(itGraphGet().at.get({CJ}))"), f'{w}: a chain end not seen within the keep time: no ring (Q13)')
        # merge keeps IDs; docked adds nothing; the switch off adds nothing
        pg.evaluate(f"(() => {{ const r = itWhStore().rep[{RENS}]; r.sigs = [Object.assign(itWhSigNew('QQQ-111', false, '', false), {{t: Date.now(), who: 'Mk Scout Alt'}})]; whSeen({RENS}, Date.now() + 1000, false); whSeen(RTJ.C, Date.now() + 2000, false); }})()")
        ok(pg.evaluate(f"itWhStore().rep[{RENS}].sigs.some(s => s.sig === 'QQQ-111') && !itWhStore().rep[{RENS}].jw.out"), f'{w}: a jump merges into the report and keeps its IDs')
        pg.evaluate(f"whSeen({JITA}, Date.now() + 3000, false)")
        ok(pg.evaluate(f"!!(itWhStore().rep[{JITA}] && itWhStore().rep[{JITA}].jw.out)"), f'{w}: coming out of the chain adds that exit too (Q9)')
        pg.evaluate(f"whSeen(RTJ.A, Date.now() + 4000, true)")
        ok(pg.evaluate(f"itWhStore().rep[{JITA}].jw.out && !whLinkOf({JITA}, RTJ.A)"), f'{w}: arriving docked adds nothing')
        scene(pg, 'set')
        ok(pg.evaluate("!!document.querySelector('[data-rt-jw]') && document.querySelector('[data-rt-jw]').checked"), f'{w}: the switch in Intel settings, on')
        pg.evaluate("document.querySelector('[data-rt-jw]').click()")
        pg.evaluate(f"whSeen({AMARR}, Date.now() + 5000, false)")
        ok(not pg.evaluate(f"!!itWhStore().rep[{AMARR}]"), f'{w}: switch off: nothing added')
        pg.screenshot(path=f'{SHOTS}/set_{w}.png')
        ok(pg.evaluate("document.scrollingElement.scrollWidth <= innerWidth + 1"), f'{w}: no sideways scroll')
        ok(not errs, f'{w}: no page errors {errs[:2]}')
        b.close()
print(f'{n - len(fails)} of {n} checks pass')
sys.exit(1 if fails else 0)
